INSERT INTO public.oracle_cards (oracle_id, code, name, number, suit, keywords, description) VALUES
  ((SELECT id FROM iching), 'hexagrama_1', 'O Criativo (Qian)', 1, 'hexagramas', ARRAY['criatividade', 'poder', 'iniciativa', 'expansao'], 'O Criativo representa o ceu, a forca criativa primordial, a acao decidida e a energia yang em sua plenitude.' || chr(10) || 'Palavras-chave: poder criativo, acao, iniciativa, expansao.'),
  ((SELECT id FROM iching), 'hexagrama_2', 'O Receptivo (Kun)', 2, 'hexagramas', ARRAY['receptividade', 'entrega', 'nutricao', 'humildade'], 'O Receptivo simboliza a terra, a devocao receptiva que nutre todas as coisas com paciencia e humildade.' || chr(10) || 'Palavras-chave: receptividade, entrega, nutricao, humildade.'),
  ((SELECT id FROM iching), 'hexagrama_3', 'A Dificuldade Inicial (Zhun)', 3, 'hexagramas', ARRAY['inicio', 'dificuldade', 'persistencia', 'paciencia'], 'A Dificuldade Inicial representa o parto de algo novo, onde o crescimento enfrenta obstaculos que exigem paciencia e persistencia.' || chr(10) || 'Palavras-chave: inicio, dificuldade, persistencia, paciencia.'),
  ((SELECT id FROM iching), 'hexagrama_4', 'A Insensatez Juvenil (Meng)', 4, 'hexagramas', ARRAY['aprendizado', 'inexperiencia', 'ensino', 'abertura'], 'A Insensatez Juvenil retrata a inexperiencia que busca orientacao, o momento de aprender com humildade e mente aberta.' || chr(10) || 'Palavras-chave: aprendizado, inexperiencia, ensino, abertura.'),
  ((SELECT id FROM iching), 'hexagrama_5', 'A Espera (Xu)', 5, 'hexagramas', ARRAY['paciencia', 'espera', 'preparacao', 'confianca'], 'A Espera ensina que ha momentos em que a acao certa e esperar com paciencia e confianca no timing divino.' || chr(10) || 'Palavras-chave: paciencia, espera, preparacao, confianca.'),
  ((SELECT id FROM iching), 'hexagrama_6', 'O Conflito (Song)', 6, 'hexagramas', ARRAY['conflito', 'disputa', 'justica', 'equilibrio'], 'O Conflito alerta para a necessidade de enfrentar disputas com justica e equilibrio, evitando a beligerancia desnecessaria.' || chr(10) || 'Palavras-chave: conflito, disputa, justica, equilibrio.'),
  ((SELECT id FROM iching), 'hexagrama_7', 'O Exercito (Shi)', 7, 'hexagramas', ARRAY['estrategia', 'lideranca', 'disciplina', 'acao_coletiva'], 'O Exercito representa a forca organizada, a lideranca disciplinada e a acao coletiva em direcao a um objetivo comum.' || chr(10) || 'Palavras-chave: estrategia, lideranca, disciplina, acao coletiva.'),
  ((SELECT id FROM iching), 'hexagrama_8', 'A Uniao (Bi)', 8, 'hexagramas', ARRAY['uniao', 'cooperacao', 'alianca', 'harmonia'], 'A Uniao simboliza a forca que surge da cooperacao harmoniosa entre pessoas que compartilham um proposito comum.' || chr(10) || 'Palavras-chave: uniao, cooperacao, alianca, harmonia.'),
  ((SELECT id FROM iching), 'hexagrama_9', 'O Poder Domestico (Xiao Chu)', 9, 'hexagramas', ARRAY['paciencia', 'acumulo', 'disciplina', 'progresso_lento'], 'O Poder Domestico indica a forca contida que se acumula aos poucos, exigindo disciplina e paciencia para germinar.' || chr(10) || 'Palavras-chave: paciencia, acumulo, disciplina, progresso lento.'),
  ((SELECT id FROM iching), 'hexagrama_10', 'A Conduta (Lu)', 10, 'hexagramas', ARRAY['conduta', 'prudencia', 'cortesia', 'respeito'], 'A Conduta ensina que pisar com leveza e consciencia, agindo com cortesia e respeito, e o caminho para a estabilidade.' || chr(10) || 'Palavras-chave: conduta, prudencia, cortesia, respeito.'),
  ((SELECT id FROM iching), 'hexagrama_11', 'A Paz (Tai)', 11, 'hexagramas', ARRAY['paz', 'prosperidade', 'harmonia', 'equilibrio'], 'A Paz representa o equilibrio perfeito entre ceu e terra, um tempo de prosperidade, harmonia e fluencia natural.' || chr(10) || 'Palavras-chave: paz, prosperidade, harmonia, equilibrio.'),
  ((SELECT id FROM iching), 'hexagrama_12', 'A Estagnacao (Pi)', 12, 'hexagramas', ARRAY['estagnacao', 'declinio', 'retirada', 'reflexao'], 'A Estagnacao marca um periodo de declinio e isolamento, convidando a retirada estrategica e a reflexao interior.' || chr(10) || 'Palavras-chave: estagnacao, declinio, retirada, reflexao.'),
  ((SELECT id FROM iching), 'hexagrama_13', 'A Comunhao (Tong Ren)', 13, 'hexagramas', ARRAY['fraternidade', 'cooperacao', 'comunidade', 'amizade'], 'A Comunhao celebra a uniao entre pessoas que se reconhecem como iguais, cultivando fraternidade e cooperacao.' || chr(10) || 'Palavras-chave: fraternidade, cooperacao, comunidade, amizade.'),
  ((SELECT id FROM iching), 'hexagrama_14', 'A Grande Posse (Da You)', 14, 'hexagramas', ARRAY['abundancia', 'prosperidade', 'generosidade', 'sucesso'], 'A Grande Posse e a abundancia conquistada com integridade, um momento de colher frutos e compartilhar com generosidade.' || chr(10) || 'Palavras-chave: abundancia, prosperidade, generosidade, sucesso.'),
  ((SELECT id FROM iching), 'hexagrama_15', 'A Modestia (Qian)', 15, 'hexagramas', ARRAY['modestia', 'humildade', 'simplicidade', 'equilibrio'], 'A Modestia ensina que a verdadeira grandeza se manifesta na simplicidade e na humildade de quem nao precisa se exaltar.' || chr(10) || 'Palavras-chave: modestia, humildade, simplicidade, equilibrio.'),
  ((SELECT id FROM iching), 'hexagrama_16', 'O Entusiasmo (Yu)', 16, 'hexagramas', ARRAY['entusiasmo', 'alegria', 'inspiracao', 'energia'], 'O Entusiasmo e a energia contagiante que inspira e mobiliza, a alegria que prepara o terreno para grandes realizacoes.' || chr(10) || 'Palavras-chave: entusiasmo, alegria, inspiracao, energia.'),
  ((SELECT id FROM iching), 'hexagrama_17', 'O Seguimento (Sui)', 17, 'hexagramas', ARRAY['adaptacao', 'seguimento', 'movimento', 'fluxo'], 'O Seguimento convida a adaptar-se ao fluxo natural das circunstancias, seguindo o movimento sem resistencia.' || chr(10) || 'Palavras-chave: adaptacao, seguimento, movimento, fluxo.'),
  ((SELECT id FROM iching), 'hexagrama_18', 'O Trabalho Corretivo (Gu)', 18, 'hexagramas', ARRAY['reparacao', 'renovacao', 'disciplina', 'melhoria'], 'O Trabalho Corretivo revela a necessidade de reparar erros passados e renovar estruturas com disciplina e atencao aos detalhes.' || chr(10) || 'Palavras-chave: reparacao, renovacao, disciplina, melhoria.'),
  ((SELECT id FROM iching), 'hexagrama_19', 'A Aproximacao (Lin)', 19, 'hexagramas', ARRAY['aproximacao', 'crescimento', 'oportunidade', 'progresso'], 'A Aproximacao anuncia um periodo de crescimento e oportunidades, onde o progresso se da pela aproximacao gradual e constante.' || chr(10) || 'Palavras-chave: aproximacao, crescimento, oportunidade, progresso.'),
  ((SELECT id FROM iching), 'hexagrama_20', 'A Contemplacao (Guan)', 20, 'hexagramas', ARRAY['contemplacao', 'observacao', 'reflexao', 'entendimento'], 'A Contemplacao convida a observar com atencao e silencio, buscando compreender a essencia antes de agir.' || chr(10) || 'Palavras-chave: contemplacao, observacao, reflexao, entendimento.'),
  ((SELECT id FROM iching), 'hexagrama_21', 'A Mordida Decisiva (Shi He)', 21, 'hexagramas', ARRAY['justica', 'decisao', 'superacao', 'verdade'], 'A Mordida Decisiva representa a acao firme de cortar o que ja nao serve, aplicando justica e verdade com determinacao.' || chr(10) || 'Palavras-chave: justica, decisao, superacao, verdade.'),
  ((SELECT id FROM iching), 'hexagrama_22', 'A Graca (Bi)', 22, 'hexagramas', ARRAY['beleza', 'graca', 'harmonia', 'sutileza'], 'A Graca celebra a beleza sutil que emana da harmonia interna, o encanto que nao precisa de excessos para brilhar.' || chr(10) || 'Palavras-chave: beleza, graca, harmonia, sutileza.'),
  ((SELECT id FROM iching), 'hexagrama_23', 'O Esfacelamento (Bo)', 23, 'hexagramas', ARRAY['ruptura', 'desgaste', 'renovacao', 'desapego'], 'O Esfacelamento mostra que tudo que e solido se desgasta com o tempo, abrindo espaco para a renovacao pelo desapego.' || chr(10) || 'Palavras-chave: ruptura, desgaste, renovacao, desapego.'),
  ((SELECT id FROM iching), 'hexagrama_24', 'O Retorno (Fu)', 24, 'hexagramas', ARRAY['retorno', 'renovacao', 'recomeco', 'ciclo'], 'O Retorno celebra o momento do recomeco, quando a luz retorna apos a escuridao e um novo ciclo se inicia.' || chr(10) || 'Palavras-chave: retorno, renovacao, recomeco, ciclo.'),
  ((SELECT id FROM iching), 'hexagrama_25', 'A Inocencia (Wu Wang)', 25, 'hexagramas', ARRAY['inocencia', 'espontaneidade', 'simplicidade', 'verdade'], 'A Inocencia e a acao pura e espontanea que flui sem expectativas, confiando na simplicidade do ser.' || chr(10) || 'Palavras-chave: inocencia, espontaneidade, simplicidade, verdade.'),
  ((SELECT id FROM iching), 'hexagrama_26', 'A Forca Domestica (Da Chu)', 26, 'hexagramas', ARRAY['forca_interior', 'acumulo', 'paciencia', 'autocontrole'], 'A Forca Domestica e o poder interior cultivado com disciplina e paciencia, a forca que se acumula em silencio.' || chr(10) || 'Palavras-chave: forca interior, acumulo, paciencia, autocontrole.'),
  ((SELECT id FROM iching), 'hexagrama_27', 'O Alimento (Yi)', 27, 'hexagramas', ARRAY['nutricao', 'sustento', 'equilibrio', 'saude'], 'O Alimento fala da necessidade de nutrir o corpo e o espirito com equilibrio, buscando o sustento que vem da harmonia.' || chr(10) || 'Palavras-chave: nutricao, sustento, equilibrio, saude.'),
  ((SELECT id FROM iching), 'hexagrama_28', 'O Excesso do Grande (Da Guo)', 28, 'hexagramas', ARRAY['excesso', 'desequilibrio', 'correcao', 'moderacao'], 'O Excesso do Grande alerta para os perigos do desequilibrio e do exagero, convidando a correcao pela moderacao.' || chr(10) || 'Palavras-chave: excesso, desequilibrio, correcao, moderacao.'),
  ((SELECT id FROM iching), 'hexagrama_29', 'O Abismal (Kan)', 29, 'hexagramas', ARRAY['perigo', 'desafio', 'superacao', 'resiliencia'], 'O Abismal representa o perigo e os desafios profundos que testam a resiliencia, exigindo coragem para atravessar o abismo.' || chr(10) || 'Palavras-chave: perigo, desafio, superacao, resiliencia.'),
  ((SELECT id FROM iching), 'hexagrama_30', 'O Agarrado (Li)', 30, 'hexagramas', ARRAY['clareza', 'consciencia', 'iluminacao', 'discernimento'], 'O Agarrado e o fogo da consciencia que ilumina a verdade, a clareza que permite enxergar alem das ilusoes.' || chr(10) || 'Palavras-chave: clareza, consciencia, iluminacao, discernimento.'),
  ((SELECT id FROM iching), 'hexagrama_31', 'A Atracao (Xian)', 31, 'hexagramas', ARRAY['atracao', 'influencia', 'conexao', 'sentimento'], 'A Atracao fala da forca magnetica que une os seres, a influencia sutil que flui entre coracoes e almas.' || chr(10) || 'Palavras-chave: atracao, influencia, conexao, sentimento.'),
  ((SELECT id FROM iching), 'hexagrama_32', 'A Perseveranca (Heng)', 32, 'hexagramas', ARRAY['persistencia', 'constancia', 'duracao', 'compromisso'], 'A Perseveranca celebra a constancia que sustenta relacoes e projetos ao longo do tempo, a forca que persiste sem se exaurir.' || chr(10) || 'Palavras-chave: persistencia, constancia, duracao, compromisso.'),
  ((SELECT id FROM iching), 'hexagrama_33', 'O Recuo (Dun)', 33, 'hexagramas', ARRAY['recuo', 'estrategia', 'desapego', 'pausa'], 'O Recuo ensina que as vezes a melhor acao e recuar com estrategia, criando espaco para uma nova perspectiva.' || chr(10) || 'Palavras-chave: recuo, estrategia, desapego, pausa.'),
  ((SELECT id FROM iching), 'hexagrama_34', 'O Grande Poder (Da Zhuang)', 34, 'hexagramas', ARRAY['poder', 'vitalidade', 'audacia', 'expansao'], 'O Grande Poder e a forca vital em plena expansao, a audacia que impulsiona avancos ousados e confiantes.' || chr(10) || 'Palavras-chave: poder, vitalidade, audacia, expansao.'),
  ((SELECT id FROM iching), 'hexagrama_35', 'O Progresso (Jin)', 35, 'hexagramas', ARRAY['progresso', 'avanco', 'desenvolvimento', 'sucesso'], 'O Progresso simboliza o avanco luminoso, o crescimento visivel que resulta do esforco continuo e da perseveranca.' || chr(10) || 'Palavras-chave: progresso, avanco, desenvolvimento, sucesso.'),
  ((SELECT id FROM iching), 'hexagrama_36', 'A Obscuridade (Ming Yi)', 36, 'hexagramas', ARRAY['discricao', 'prudencia', 'resiliencia', 'paciencia'], 'A Obscuridade ensina a esconder a propria luz diante da adversidade, agindo com prudencia e paciencia ate o momento certo.' || chr(10) || 'Palavras-chave: discricao, prudencia, resiliencia, paciencia.'),
  ((SELECT id FROM iching), 'hexagrama_37', 'A Familia (Jia Ren)', 37, 'hexagramas', ARRAY['familia', 'lar', 'pertencimento', 'equilibrio'], 'A Familia representa o nucleo sagrado do lar, o pertencimento que acolhe e o equilibrio nas relacoes domesticas.' || chr(10) || 'Palavras-chave: familia, lar, pertencimento, equilibrio.'),
  ((SELECT id FROM iching), 'hexagrama_38', 'A Oposicao (Kui)', 38, 'hexagramas', ARRAY['oposicao', 'divergencia', 'conflito', 'compreensao'], 'A Oposicao revela as divergencias que separam, desafiando a buscar compreensao e encontrar pontos de convergencia.' || chr(10) || 'Palavras-chave: oposicao, divergencia, conflito, compreensao.'),
  ((SELECT id FROM iching), 'hexagrama_39', 'O Obstaculo (Jian)', 39, 'hexagramas', ARRAY['dificuldade', 'superacao', 'persistencia', 'fe'], 'O Obstaculo apresenta desafios que exigem persistencia e fe, convidando a superar as barreiras com paciencia e determinacao.' || chr(10) || 'Palavras-chave: dificuldade, superacao, persistencia, fe.'),
  ((SELECT id FROM iching), 'hexagrama_40', 'A Libertacao (Jie)', 40, 'hexagramas', ARRAY['libertacao', 'alivio', 'recomeco', 'renovacao'], 'A Libertacao marca o fim de um periodo de opressao, trazendo alivio e a oportunidade de recomecar com leveza.' || chr(10) || 'Palavras-chave: libertacao, alivio, recomeco, renovacao.'),
  ((SELECT id FROM iching), 'hexagrama_41', 'A Reducao (Sun)', 41, 'hexagramas', ARRAY['reducao', 'desapego', 'simplificacao', 'equilibrio'], 'A Reducao convida a simplificar a vida, desapegando-se do supérfluo para encontrar equilibrio e essencia.' || chr(10) || 'Palavras-chave: reducao, desapego, simplificacao, equilibrio.'),
  ((SELECT id FROM iching), 'hexagrama_42', 'O Aumento (Yi)', 42, 'hexagramas', ARRAY['aumento', 'abundancia', 'crescimento', 'beneficio'], 'O Aumento e o fluxo de abundancia que chega para beneficiar quem soube se preparar e compartilhar.' || chr(10) || 'Palavras-chave: aumento, abundancia, crescimento, beneficio.'),
  ((SELECT id FROM iching), 'hexagrama_43', 'A Decisao (Guai)', 43, 'hexagramas', ARRAY['decisao', 'corte', 'ruptura', 'escolha'], 'A Decisao exige coragem para cortar o que ja nao serve, fazendo escolhas firmes com determinacao e clareza.' || chr(10) || 'Palavras-chave: decisao, corte, ruptura, escolha.'),
  ((SELECT id FROM iching), 'hexagrama_44', 'O Encontro (Gou)', 44, 'hexagramas', ARRAY['encontro', 'encontro_inesperado', 'oportunidade', 'conexao'], 'O Encontro celebra a chegada inesperada de pessoas e oportunidades que podem transformar o rumo dos acontecimentos.' || chr(10) || 'Palavras-chave: encontro, encontro inesperado, oportunidade, conexao.'),
  ((SELECT id FROM iching), 'hexagrama_45', 'A Reuniao (Cui)', 45, 'hexagramas', ARRAY['reuniao', 'comunidade', 'uniao', 'harmonia'], 'A Reuniao agrupa pessoas com interesses comuns, criando comunidade e uniao harmoniosa em torno de um proposito.' || chr(10) || 'Palavras-chave: reuniao, comunidade, uniao, harmonia.'),
  ((SELECT id FROM iching), 'hexagrama_46', 'A Ascensao (Sheng)', 46, 'hexagramas', ARRAY['ascensao', 'progresso', 'promocao', 'crescimento'], 'A Ascensao e o movimento ascendente do crescimento, o progresso que leva a novos patamares de realizacao.' || chr(10) || 'Palavras-chave: ascensao, progresso, promocao, crescimento.'),
  ((SELECT id FROM iching), 'hexagrama_47', 'A Opressao (Kun)', 47, 'hexagramas', ARRAY['opressao', 'limitacao', 'resistencia', 'superacao'], 'A Opressao retrata o sufocamento das circunstancias adversas, testando a capacidade de resistir e encontrar saidas.' || chr(10) || 'Palavras-chave: opressao, limitacao, resistencia, superacao.'),
  ((SELECT id FROM iching), 'hexagrama_48', 'O poco (Jing)', 48, 'hexagramas', ARRAY['interior', 'profundidade', 'recurso', 'sabedoria'], 'O poco revela os recursos profundos do ser interior, a sabedoria que brota quando se acessa as aguas da alma.' || chr(10) || 'Palavras-chave: interior, profundidade, recurso, sabedoria.'),
  ((SELECT id FROM iching), 'hexagrama_49', 'A Revolucao (Ge)', 49, 'hexagramas', ARRAY['revolucao', 'mudanca', 'transformacao', 'renovacao'], 'A Revolucao anuncia mudancas profundas e necessarias, a transformacao que rompe com o velho para dar lugar ao novo.' || chr(10) || 'Palavras-chave: revolucao, mudanca, transformacao, renovacao.'),
  ((SELECT id FROM iching), 'hexagrama_50', 'O Caldeirao (Ding)', 50, 'hexagramas', ARRAY['transformacao', 'alquimia', 'criacao', 'nutricao'], 'O Caldeirao e o vaso alquímico onde ocorre a transformacao, a criacao que se alimenta do fogo interior.' || chr(10) || 'Palavras-chave: transformacao, alquimia, criacao, nutricao.'),
  ((SELECT id FROM iching), 'hexagrama_51', 'O Despertar (Zhen)', 51, 'hexagramas', ARRAY['choque', 'despertar', 'movimento', 'transformacao'], 'O Despertar vem como um trovão que sacode a alma, provocando movimento e transformacao repentina.' || chr(10) || 'Palavras-chave: choque, despertar, movimento, transformacao.'),
  ((SELECT id FROM iching), 'hexagrama_52', 'A Imobilidade (Gen)', 52, 'hexagramas', ARRAY['quietude', 'meditacao', 'introspeccao', 'estabilidade'], 'A Imobilidade convida a parar e silenciar, encontrando na quietude a estabilidade e a paz interior.' || chr(10) || 'Palavras-chave: quietude, meditacao, introspeccao, estabilidade.'),
  ((SELECT id FROM iching), 'hexagrama_53', 'O Desenvolvimento (Jian)', 53, 'hexagramas', ARRAY['progresso_lento', 'paciencia', 'evolucao', 'maturidade'], 'O Desenvolvimento segue o ritmo paciente da natureza, crescendo passo a passo ate atingir a maturidade plena.' || chr(10) || 'Palavras-chave: progresso lento, paciencia, evolucao, maturidade.'),
  ((SELECT id FROM iching), 'hexagrama_54', 'A Donzela Casadoura (Gui Mei)', 54, 'hexagramas', ARRAY['uniao', 'transicao', 'equilibrio', 'aceitacao'], 'A Donzela Casadoura fala das transicoes e unioes que exigem equilibrio e aceitacao das circunstancias.' || chr(10) || 'Palavras-chave: uniao, transicao, equilibrio, aceitacao.'),
  ((SELECT id FROM iching), 'hexagrama_55', 'A Abundancia (Feng)', 55, 'hexagramas', ARRAY['abundancia', 'plenitude', 'prosperidade', 'gratidao'], 'A Abundancia celebra a plenitude que transborda, o apogeu da prosperidade que inspira gratidao e generosidade.' || chr(10) || 'Palavras-chave: abundancia, plenitude, prosperidade, gratidao.'),
  ((SELECT id FROM iching), 'hexagrama_56', 'O Andarilho (Lu)', 56, 'hexagramas', ARRAY['viagem', 'exploracao', 'desapego', 'aprendizado'], 'O Andarilho e o viajante que explora o desconhecido, aprendendo com cada experiencia e cultivando o desapego.' || chr(10) || 'Palavras-chave: viagem, exploracao, desapego, aprendizado.'),
  ((SELECT id FROM iching), 'hexagrama_57', 'O Suave (Xun)', 57, 'hexagramas', ARRAY['penetracao', 'suavidade', 'flexibilidade', 'adaptacao'], 'O Suave penetra como o vento, com delicadeza e persistencia, adaptando-se sem perder sua direcao.' || chr(10) || 'Palavras-chave: penetracao, suavidade, flexibilidade, adaptacao.'),
  ((SELECT id FROM iching), 'hexagrama_58', 'A Alegria (Dui)', 58, 'hexagramas', ARRAY['alegria', 'satisfacao', 'comunhao', 'otimismo'], 'A Alegria e o lago cristalino que reflete a serenidade, a comunhao que brota da satisfacao genuina e do otimismo.' || chr(10) || 'Palavras-chave: alegria, satisfacao, comunhao, otimismo.'),
  ((SELECT id FROM iching), 'hexagrama_59', 'A Dispersao (Huan)', 59, 'hexagramas', ARRAY['dispersao', 'liberacao', 'renovacao', 'clareza'], 'A Dispersao dissolve as nuvens da confusao, trazendo clareza e libertacao das amarras emocionais.' || chr(10) || 'Palavras-chave: dispersao, liberacao, renovacao, clareza.'),
  ((SELECT id FROM iching), 'hexagrama_60', 'A Limitacao (Jie)', 60, 'hexagramas', ARRAY['limite', 'disciplina', 'equilibrio', 'moderacao'], 'A Limitacao ensina que os limites sao necessarios para ordenar a vida, trazendo disciplina e moderacao.' || chr(10) || 'Palavras-chave: limite, disciplina, equilibrio, moderacao.'),
  ((SELECT id FROM iching), 'hexagrama_61', 'A Verdade Interior (Zhong Fu)', 61, 'hexagramas', ARRAY['sinceridade', 'confianca', 'verdade', 'integridade'], 'A Verdade Interior e a sinceridade que emana do coracao, a confianca que nasce da integridade e da autenticidade.' || chr(10) || 'Palavras-chave: sinceridade, confianca, verdade, integridade.'),
  ((SELECT id FROM iching), 'hexagrama_62', 'A Pequena Preponderancia (Xiao Guo)', 62, 'hexagramas', ARRAY['humildade', 'moderacao', 'prudencia', 'atencao'], 'A Pequena Preponderancia recomenda humildade e moderacao, prestando atencao aos pequenos detalhes que fazem a diferenca.' || chr(10) || 'Palavras-chave: humildade, moderacao, prudencia, atencao.'),
  ((SELECT id FROM iching), 'hexagrama_63', 'A Consumacao (Ji Ji)', 63, 'hexagramas', ARRAY['realizacao', 'completude', 'equilibrio', 'sucesso'], 'A Consumacao e a realizacao plena de um ciclo, o equilibrio alcancado apos a superacao de todos os desafios.' || chr(10) || 'Palavras-chave: realizacao, completude, equilibrio, sucesso.'),
  ((SELECT id FROM iching), 'hexagrama_64', 'Antes da Consumacao (Wei Ji)', 64, 'hexagramas', ARRAY['transicao', 'expectativa', 'potencial', 'futuro'], 'Antes da Consumacao e o momento de transicao entre ciclos, onde tudo ainda e potencial e o futuro espera para se revelar.' || chr(10) || 'Palavras-chave: transicao, expectativa, potencial, futuro.')
